    let expected_kind = ErrorKind::UnknownArgument;
    static MESSAGE: &str = "\
error: unexpected argument '--cwd <current-dir-unknown>' found

  tip: a similar argument exists: '-C'
  tip: not much else to say

Usage: test [OPTIONS]

For more information, try '--help'.
";
