fn push_arg_values(
    &self,
    arg: &Arg,
    raw_vals: Vec<OsString>,
    source: ValueSource,
    matcher: &mut ArgMatcher,
) -> ClapResult<()> {
    debug!("Parser::push_arg_values: {raw_vals:?}");

    for raw_val in raw_vals {
        // update the current index because each value is a distinct index to clap
        self.cur_idx.set(self.cur_idx.get() + 1);
        debug!(
            "Parser::add_single_val_to_arg: cur_idx:={}",
            self.cur_idx.get()
        );
        // Flag-like actions (`SetTrue`, `SetFalse`, `Count`) synthesize their own
        // internal, non-user-facing values when the argument wasn't present on the
        // command line (e.g. the implicit `false` default for `SetTrue`).  Route these
        // through the action's own parser rather than the user's `value_parser`, as the
        // latter may be intended purely for validating real command-line input (see
        // `UnknownArgumentValueParser`) and shouldn't be run against synthetic values.
        let value_parser = if source == ValueSource::DefaultValue && !arg.is_takes_value_set()
        {
            arg.get_action()
                .default_value_parser()
                .unwrap_or_else(|| arg.get_value_parser().clone())
        } else {
            arg.get_value_parser().clone()
        };
        let val = ok!(value_parser.parse_ref(self.cmd, Some(arg), &raw_val));

